    paren_string = paren_string.replace(" ", "")

    def is_balanced(s: str) -> bool:
        """ Helper function to check if the string is balanced."""
        stack = []
        for char in s:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack or stack.pop() != "(":
                    return False
        return not stack

    def separate_groups(s: str) -> List[str]:
        """ Helper function to recursively separate the groups."""
        if not s:
