def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c ab') == {'a': 2, 'b': 2}
    histogram('bbba') == {'b': 4}
    histogram('') == {}
    """
    if not test:
        return {}

    # Convert the string to lowercase and split into a list of characters
    test = test.lower()
    test = [char for char in test if char.isalpha()]

    # Count the occurrences of each character
    char_count = {}
    for char in test:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the maximum occurrence count
    max_count = max(char_count.values(), default=0)

    # Filter the dictionary to only include characters that have the maximum occurrence count
    result = {char: count for char, count in char_count.items() if count == max_count}

    return result
