        raise ValueError("Number must be between 1 and 1000, inclusive.")

    numeral_map = {
        1000: 'm', 900: 'cm', 500: 'd', 400: 'cd', 100: 'c', 90: 'xc', 50: 'l', 40: 'xl', 10: 'x', 9: 'ix', 5: 'v', 4: 'iv', 1: 'i'
    }

    roman_numerals = []
    for value in sorted(numeral_map.keys(), reverse=True):
        while number >= value:
